if($_SERVER['REQUEST_METHOD']==='POST'){
    csrf_check();
    try{
        if(!$valid)throw new RuntimeException('Invite Link นี้หมดอายุ ถูกใช้แล้ว หรือไม่พร้อมใช้งาน กรุณาขอลิงก์ใหม่จาก Admin');
        $username=trim((string)($_POST['username']??''));$pw=(string)($_POST['password']??'');$confirm=(string)($_POST['password_confirm']??'');if($pw!==$confirm)throw new RuntimeException('ยืนยัน Password ไม่ตรงกัน');
        $hash=account_invite_hash($token);$inviteId=(int)($invite['id']??0);$employeeId=(int)$employee['id'];$createdUser=null;
        db_mutate(function($x)use($hash,$inviteId,$employeeId,$username,$pw,&$createdUser){
            $idx=null;foreach($x['account_invites']??[] as $i=>$row)if((int)($row['id']??0)===$inviteId&&hash_equals((string)($row['token_hash']??''),$hash)){$idx=$i;break;}if($idx===null||!account_invite_is_valid($x['account_invites'][$idx]))throw new RuntimeException('Invite Link ไม่พร้อมใช้งานแล้ว');
            $createdUser=account_create_and_link($x,$employeeId,$username,$pw);$x['account_invites'][$idx]['used_at']=date('c');$x['account_invites'][$idx]['used_by_user_id']=(int)$createdUser['id'];
            foreach($x['account_invites'] as $i=>&$other)if($i!==$idx&&(int)($other['employee_id']??0)===$employeeId&&account_invite_is_valid($other))$other['revoked_at']=date('c');unset($other);
            $x['audit'][]=['at'=>date('c'),'action'=>'employee_self_account_activated','employee_id'=>$employeeId,'user_id'=>(int)$createdUser['id'],'invite_id'=>$inviteId,'role'=>(string)$createdUser['role']];return $x;
        });
        if(!$createdUser)throw new RuntimeException('สร้างบัญชีไม่สำเร็จ');establish_session($createdUser);$_SESSION['needs_pin_setup']=1;header('Location:setup-pin.php?return_to=time');exit;
    }catch(Throwable $e){$err=$e->getMessage();$d=db_load();$invite=account_find_invite($d,$token);$employee=$invite?workforce_employee_by_id($d,(int)($invite['employee_id']??0)):null;$valid=$invite&&account_invite_is_valid($invite)&&$employee&&!empty($employee['active'])&&empty($employee['user_id']);}
}
$role=$employee?account_employee_role($employee):'';$expires=$invite&&!empty($invite['expires_at'])?date('d/m/Y H:i',strtotime((string)$invite['expires_at'])):'';
